20	__aicore__ inline void CopyTiling(HistcTiling* tiling, GM_ADDR tilingGM) {
21	    GlobalTensor<uint64_t> tilingGm;
22	    tilingGm.SetGlobalBuffer(reinterpret_cast<__gm__ uint64_t*>(tilingGM));
23	
24	    tiling->totalLength = tilingGm.GetValue(0);
25	    tiling->bins = tilingGm.GetValue(1);
