33	template <typename T>
34	class KernelHistc {
35	public:
36	    __aicore__ inline KernelHistc() {}
37	
38	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR out, GM_ADDR tiling) {
39	        CopyTiling(&tiling_, tiling);
40	
41	        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x));
42	        outGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(out));
43	    }
44	
45	    __aicore__ inline void Process() {
46	        int64_t coreIdx = GetBlockIdx();
47	
48	        if (coreIdx != 0) {
49	            return;
50	        }
51	
52	        int64_t totalElems = tiling_.totalLength;
53	        if (totalElems <= 0) {
54	            return;
55	        }
56	
57	        float range = tiling_.max_val - tiling_.min_val;
58	        float scale = (range > 0.0f) ? static_cast<float>(tiling_.bins) / range : 0.0f;
59	
60	        // Initialize output histogram to zero
61	        for (int64_t i = 0; i < tiling_.bins; ++i) {
62	            outGm.SetValue(i, T(0));
63	        }
64	
65	        // Process each element and accumulate histogram
66	        for (int64_t i = 0; i < totalElems; ++i) {
67	            float val = static_cast<float>(xGm.GetValue(i));
68	
69	            // Skip values outside [min, max] range (PyTorch histc behavior)
70	            if (val < tiling_.min_val || val > tiling_.max_val) {
71	                continue;
72	            }
73	
74	            float shifted = val - tiling_.min_val;
75	            float scaled = shifted * scale;
76	            int32_t binIdx = static_cast<int32_t>(scaled);
77	            // Clamp to valid bin range (for values exactly at max boundary)
78	            if (binIdx < 0) binIdx = 0;
79	            if (binIdx >= tiling_.bins) binIdx = tiling_.bins - 1;
80	
81	            float count = static_cast<float>(outGm.GetValue(binIdx));
82	            outGm.SetValue(binIdx, static_cast<T>(count + 1.0f));
83	        }
84	    }
85	
86	private:
87	    GlobalTensor<T> xGm;
88	    GlobalTensor<T> outGm;
89	
90	    HistcTiling tiling_;
91	};
