20	    // Input validation
21	    TORCH_CHECK(self.is_contiguous(), "histc: input must be contiguous");
22	    TORCH_CHECK(bins > 0, "histc: bins must be positive");
23	    TORCH_CHECK(min_val < max_val, "histc: min must be less than max");
24	
25	    int64_t num_elements = self.numel();
26	    auto output = at::zeros({bins}, at::TensorOptions().dtype(self.dtype()).device(self.device()));
27	
28	    if (num_elements == 0) {
29	        return output;
30	    }
31	
32	    // Use single core for correctness (histc requires accumulation to shared bins)
33	    int64_t used_core_num = 1;
34	
35	    // Tiling parameters
36	    int64_t tile_length = 256;  // elements per tile
37	
38	    // Prepare tiling data on device
39	    // Layout: [totalLength, bins, min_val, max_val, tileLength]
40	    auto tiling_data = at::zeros({10}, at::TensorOptions().dtype(at::kLong).device(self.device()));
41	    auto tiling_cpu = at::zeros({10}, at::TensorOptions().dtype(at::kLong));
42	    int64_t* tiling_ptr = tiling_cpu.data_ptr<int64_t>();
43	    tiling_ptr[0] = num_elements;
44	    tiling_ptr[1] = bins;
45	    *reinterpret_cast<float*>(&tiling_ptr[2]) = min_val;
46	    *reinterpret_cast<float*>(&tiling_ptr[3]) = max_val;
47	    tiling_ptr[4] = tile_length;
48	    tiling_data.copy_(tiling_cpu);
49	
50	    // Cast to left values for EXEC_KERNEL_CMD
51	    float min_val_f = min_val;
52	    float max_val_f = max_val;
53	    int64_t bins_i = bins;
54	    int64_t num_elements_i = num_elements;
55	
56	    // Launch kernel
57	    if (self.dtype() == at::kFloat) {
58	        EXEC_KERNEL_CMD(histc_fp32, used_core_num, self, output, tiling_data);
59	    } else if (self.dtype() == at::kHalf) {
