#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t TILE_SIZE = 1024;  // elements per UB tile

// Tiling data structure
struct HistogramV2Tiling {
    int64_t totalLength;
    int64_t bins;
    float minVal;
    float maxVal;
};

// CopyTiling helper — read tiling data from GM
__aicore__ inline void CopyTiling(HistogramV2Tiling* tiling, GM_ADDR tilingGM) {
    GlobalTensor<uint64_t> tilingGm;
    tilingGm.SetGlobalBuffer(reinterpret_cast<__gm__ uint64_t*>(tilingGM));

    tiling->totalLength = static_cast<int64_t>(tilingGm.GetValue(0));
    tiling->bins = static_cast<int64_t>(tilingGm.GetValue(1));

    uint64_t minRaw = tilingGm.GetValue(2);
    uint64_t maxRaw = tilingGm.GetValue(3);
    tiling->minVal = *reinterpret_cast<float*>(&minRaw);
    tiling->maxVal = *reinterpret_cast<float*>(&maxRaw);
}

class KernelHistogramV2 {
public:
    __aicore__ inline KernelHistogramV2() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR out, GM_ADDR tiling) {
        CopyTiling(&tiling_, tiling);

        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(x));
        outGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(out));
    }

    __aicore__ inline void Process() {
        int64_t coreIdx = GetBlockIdx();
        if (coreIdx != 0) {
            return;
        }

        int64_t totalElems = tiling_.totalLength;
        if (totalElems <= 0) {
            return;
        }

        int64_t bins = tiling_.bins;

        float range = tiling_.maxVal - tiling_.minVal;
        float scale = (range > 0.0f) ? static_cast<float>(bins) / range : 0.0f;

        constexpr int64_t bufLen = (TILE_SIZE * sizeof(float) + 31) / 32 * 32 / sizeof(float);

        // Allocate local histogram buffer in UB (int32)
        LocalTensor<int32_t> localHist = TBufAlloc<int32_t>(bins);
        Duplicate(localHist, int32_t(0), bins);

        // Allocate compute buffers in UB (float32)
        LocalTensor<float> xTile = TBufAlloc<float>(bufLen);
        LocalTensor<float> shifted = TBufAlloc<float>(bufLen);
        LocalTensor<float> scaled = TBufAlloc<float>(bufLen);
        LocalTensor<int32_t> binIndices = TBufAlloc<int32_t>(bufLen);

        int64_t numTiles = (totalElems + TILE_SIZE - 1) / TILE_SIZE;
        for (int64_t t = 0; t < numTiles; ++t) {
            int64_t tileStart = t * TILE_SIZE;
            int64_t tileEnd = (tileStart + TILE_SIZE > totalElems)
                              ? totalElems : tileStart + TILE_SIZE;
            int64_t tileLen = tileEnd - tileStart;

            // CopyIn: load tile from GM to UB
            DataCopyPadParams<float> copyPadParams;
            DataCopyPad(xTile, xGm[tileStart],
                DataCopyExtParams{1, static_cast<uint32_t>(tileLen * sizeof(float)), 0, 0},
                copyPadParams);
            PipeBarrier<PIPE_MTE2>();

            // Step 1: shifted = xTile - minVal
            Adds(shifted, xTile, -tiling_.minVal, tileLen);

            // Step 2: scaled = shifted * scale
            Muls(scaled, shifted, scale, tileLen);

            // Step 3: bin_indices = floor(scaled) — cast float to int32 with floor
            Cast(binIndices, scaled, RoundMode::CAST_FLOOR, tileLen);

            // Step 4: accumulate histogram (scalar loop — unavoidable for histogram)
            for (int64_t i = 0; i < tileLen; ++i) {
                int32_t idx = binIndices.GetValue(i);
                if (idx < 0) {
                    idx = 0;
                } else if (idx >= static_cast<int32_t>(bins)) {
                    idx = static_cast<int32_t>(bins) - 1;
                }
                int32_t curVal = localHist.GetValue(idx);
                localHist.SetValue(idx, curVal + 1);
            }
        }

        // Write final histogram to output
        DataCopyPadParams<int32_t> outPadParams;
        DataCopyPad(outGm, localHist,
            DataCopyExtParams{1, static_cast<uint32_t>(bins * sizeof(int32_t)), 0, 0},
            outPadParams);
        PipeBarrier<PIPE_MTE2>();

        // Free UB buffers
        TBufFree(binIndices);
        TBufFree(scaled);
        TBufFree(shifted);
        TBufFree(xTile);
        TBufFree(localHist);
    }

private:
    GlobalTensor<float> xGm;
    GlobalTensor<int32_t> outGm;

    HistogramV2Tiling tiling_;
};

extern "C" __global__ __aicore__ void histogram_v2(GM_ADDR x, GM_ADDR out, GM_ADDR tiling) {
    KernelHistogramV2 op;
    op.Init(x, out, tiling);
    op.Process();
}

// Alias for the build system (kebab-to-snake)
extern "C" __global__ __aicore__ void histogram_v_2(GM_ADDR x, GM_ADDR out, GM_ADDR tiling) {
    KernelHistogramV2 op;
    op.Init(x, out, tiling);
    op.Process();
}
