13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelGelu {
17	public:
18	    __aicore__ inline KernelGelu() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength,
23	                                int64_t approximate)
24	    {
25	        int64_t blockIdx = AscendC::GetBlockIdx();
26	
27	        if (formerNum > 0 && blockIdx < formerNum) {
28	            this->blockLength = formerLength;
29	            int64_t offset = blockIdx * formerLength;
30	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
31	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
32	        } else {
33	            this->blockLength = tailLength;
34	            int64_t tailIdx = (formerNum > 0) ? (blockIdx - formerNum) : blockIdx;
35	            int64_t offset = formerNum * formerLength + tailIdx * tailLength;
36	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
37	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
38	        }
39	
40	        this->tileLength = tileLength;
41	        this->approximate = approximate;
42	
43	        // Use min(tileLength, blockLength) to avoid excessive UB allocation for small inputs
44	        int64_t bufLen = (tileLength < blockLength) ? tileLength : blockLength;
45	        if (bufLen == 0 || tileLength == 0) bufLen = tileLength;
46	        if (bufLen == 0) bufLen = 16;
47	
48	        pipe.InitBuffer(inQueueX, BUFFER_NUM, bufLen * sizeof(T));
49	        pipe.InitBuffer(outQueueY, BUFFER_NUM, bufLen * sizeof(T));
50	
51	        if constexpr (sizeof(T) == 2) {
52	            pipe.InitBuffer(tmpBuf1, bufLen * sizeof(float));
53	            pipe.InitBuffer(tmpBuf2, bufLen * sizeof(float));
54	        } else {
55	            pipe.InitBuffer(tmpBuf1, bufLen * sizeof(float));
56	        }
57	    }
58	
59	    __aicore__ inline void Process()
60	    {
61	        if (this->blockLength == 0) {
62	            return;
63	        }
64	
65	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
66	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
67	
68	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
69	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
70	
71	        for (int64_t i = 0; i < tileNum - 1; ++i) {
72	            CopyIn(i, this->tileLength);
73	            Compute(i, this->tileLength);
74	            CopyOut(i, this->tileLength);
75	        }
76	        if (tileNum > 0) {
77	            CopyIn(tileNum - 1, alignedTailLen);
78	            Compute(tileNum - 1, alignedTailLen);
79	            CopyOut(tileNum - 1, alignedTailLen);
80	        }
81	    }
82	
83	private:
84	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
85	    {
86	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
87	        uint32_t blen = static_cast<uint32_t>(curTileLength * sizeof(T));
88	        if (blen == 0) blen = static_cast<uint32_t>(sizeof(T));
89	        AscendC::DataCopyExtParams copyParams{1, blen, 0, 0, 0};
90	        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
91	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
92	        inQueueX.EnQue(xLocal);
93	    }
94	
95	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
96	    {
97	        if (curTileLength == 0) return;
98	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
99	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
100	
101	        if constexpr (sizeof(T) == 2) {
102	            AscendC::LocalTensor<float> xFp32 = tmpBuf1.Get<float>();
103	            AscendC::LocalTensor<float> tmp = tmpBuf2.Get<float>();
104	
105	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
106	
107	            if (this->approximate == 0) {
108	                AscendC::Muls(tmp, xFp32, 0.707106781f, curTileLength);
109	                AscendC::Erf(tmp, tmp, curTileLength);
110	                AscendC::Adds(tmp, tmp, 1.0f, curTileLength);
111	                AscendC::Mul(tmp, xFp32, tmp, curTileLength);
112	                AscendC::Muls(tmp, tmp, 0.5f, curTileLength);
113	            } else {
114	                AscendC::Mul(tmp, xFp32, xFp32, curTileLength);
115	                AscendC::Mul(tmp, tmp, xFp32, curTileLength);
116	                AscendC::Muls(tmp, tmp, 0.044715f, curTileLength);
117	                AscendC::Add(tmp, xFp32, tmp, curTileLength);
118	                AscendC::Muls(tmp, tmp, 0.79788456f, curTileLength);
119	                AscendC::Tanh(tmp, tmp, curTileLength);
120	                AscendC::Adds(tmp, tmp, 1.0f, curTileLength);
121	                AscendC::Mul(tmp, xFp32, tmp, curTileLength);
122	                AscendC::Muls(tmp, tmp, 0.5f, curTileLength);
123	            }
124	
125	            AscendC::Cast(yLocal, tmp, AscendC::RoundMode::CAST_ROUND, curTileLength);
126	        } else {
127	            AscendC::LocalTensor<float> tmp = tmpBuf1.Get<float>();
128	
129	            if (this->approximate == 0) {
130	                AscendC::Muls(tmp, xLocal, 0.707106781f, curTileLength);
131	                AscendC::Erf(tmp, tmp, curTileLength);
132	                AscendC::Adds(tmp, tmp, 1.0f, curTileLength);
133	                AscendC::Mul(yLocal, xLocal, tmp, curTileLength);
134	                AscendC::Muls(yLocal, yLocal, 0.5f, curTileLength);
135	            } else {
136	                AscendC::Mul(tmp, xLocal, xLocal, curTileLength);
137	                AscendC::Mul(tmp, tmp, xLocal, curTileLength);
138	                AscendC::Muls(tmp, tmp, 0.044715f, curTileLength);
139	                AscendC::Add(tmp, xLocal, tmp, curTileLength);
140	                AscendC::Muls(tmp, tmp, 0.79788456f, curTileLength);
141	                AscendC::Tanh(tmp, tmp, curTileLength);
142	                AscendC::Adds(tmp, tmp, 1.0f, curTileLength);
143	                AscendC::Mul(yLocal, xLocal, tmp, curTileLength);
144	                AscendC::Muls(yLocal, yLocal, 0.5f, curTileLength);
145	            }
146	        }
147	
148	        outQueueY.EnQue<T>(yLocal);
149	        inQueueX.FreeTensor(xLocal);
150	    }
151	
152	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
153	    {
154	        if (curTileLength == 0) return;
155	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
156	        uint32_t blen = static_cast<uint32_t>(curTileLength * sizeof(T));
157	        if (blen == 0) blen = static_cast<uint32_t>(sizeof(T));
158	        AscendC::DataCopyExtParams copyParams{1, blen, 0, 0, 0};
159	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
160	        outQueueY.FreeTensor(yLocal);
161	    }
162	
163	private:
164	    AscendC::TPipe pipe;
165	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
166	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
167	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
168	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf2;
169	    AscendC::GlobalTensor<T> xGm;
170	    AscendC::GlobalTensor<T> yGm;
171	    int64_t blockLength;
172	    int64_t tileLength;
173	    int64_t approximate;
174	};
175	
176	extern "C" __global__ __aicore__ void gelu(GM_ADDR x, GM_ADDR y,
177	                                           int64_t formerNum, int64_t formerLength,
178	                                           int64_t tailLength, int64_t tileLength,
179	                                           int64_t approximate, int64_t dtypeSize)
180	{
181	    if (dtypeSize == 2) {
182	        KernelGelu<half> op;
183	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, approximate);
184	        op.Process();
185	    } else {
186	        KernelGelu<float> op;
187	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, approximate);
188	        op.Process();
189	    }
190	}
