    x_fp32 = x_fp32.reshape(-1);
    int64_t numElements = x_fp32.numel();

    // Output: int32 histogram of shape [bins]
    auto output = at::zeros({bins}, at::TensorOptions().dtype(at::kInt).device(self.device()));

    if (numElements == 0) {
        return output;
