    // Use single core for correctness (histogram requires accumulation to shared bins)
    int64_t usedCoreNum = 1;

    // Prepare tiling data
    // Layout: [totalLength, bins, min_val, max_val]
    auto tilingData = at::zeros({10}, at::TensorOptions().dtype(at::kLong).device(self.device()));
